  `user_agent` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `occurred_at` timestamp(6) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `audit_logs_entity_type_entity_id_occurred_at_index` (`entity_type`,`entity_id`,`occurred_at`),
  KEY `audit_logs_actor_user_id_occurred_at_index` (`actor_user_id`,`occurred_at`),
