  KEY `journal_entries_posted_by_foreign` (`posted_by`),
  KEY `journal_entries_entry_date_status_index` (`entry_date`,`status`),
  CONSTRAINT `journal_entries_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `journal_entries_currency_foreign` FOREIGN KEY (`currency`) REFERENCES `currencies` (`code`) ON DELETE RESTRICT,
  CONSTRAINT `journal_entries_fiscal_period_id_foreign` FOREIGN KEY (`fiscal_period_id`) REFERENCES `accounting_periods` (`id`) ON DELETE RESTRICT,
