/*!50003 CREATE*/ /*!50017 DEFINER=`erp_store`@`127.0.0.1`*/ /*!50003 TRIGGER `journal_entries_guard_update` BEFORE UPDATE ON `journal_entries` FOR EACH ROW BEGIN IF OLD.status = 'posted' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Posted journal is immutable'; END IF; IF NEW.status = 'posted' THEN IF NOT EXISTS (SELECT 1 FROM accounting_periods WHERE id=NEW.fiscal_period_id AND status='open' AND NEW.entry_date BETWEEN starts_on AND ends_on) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Posting period must be open'; END IF; IF (SELECT COUNT(*) FROM journal_lines WHERE journal_entry_id=OLD.id)<2 OR (SELECT COALESCE(SUM(debit-credit),0) FROM journal_lines WHERE journal_entry_id=OLD.id)<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Posted journal must balance'; END IF; END IF; END */;;
DELIMITER ;
