DROP TABLE IF EXISTS `sales_invoices`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sales_invoices` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `document_no` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `document_date` date NOT NULL,
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `version` int unsigned NOT NULL DEFAULT '1',
  `currency` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `base_currency` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `exchange_rate` decimal(18,8) NOT NULL,
  `exchange_rate_date` date NOT NULL,
  `exchange_rate_source` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `posted_journal_entry_id` bigint unsigned DEFAULT NULL,
  `created_by` bigint unsigned NOT NULL,
  `posted_by` bigint unsigned DEFAULT NULL,
  `posted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `customer_id` bigint unsigned NOT NULL,
  `customer_snapshot` json NOT NULL,
  `due_date` date NOT NULL,
  `sale_mode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `checkout` json NOT NULL,
  `warnings` json NOT NULL,
  `approval_id` bigint unsigned DEFAULT NULL,
  `policy_version` int unsigned NOT NULL,
  `net_total` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `tax_total` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `foreign_total` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `base_net_total` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `base_tax_total` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `base_total` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `cogs_total` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `fulfillment_status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `delivery_address` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `delivery_date` date DEFAULT NULL,
  `credit_approval_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `sales_invoices_document_no_unique` (`document_no`),
  KEY `sales_invoices_currency_foreign` (`currency`),
  KEY `sales_invoices_base_currency_foreign` (`base_currency`),
  KEY `sales_invoices_posted_journal_entry_id_foreign` (`posted_journal_entry_id`),
  KEY `sales_invoices_created_by_foreign` (`created_by`),
  KEY `sales_invoices_posted_by_foreign` (`posted_by`),
  KEY `sales_invoices_status_document_date_index` (`status`,`document_date`),
  KEY `sales_invoices_approval_id_foreign` (`approval_id`),
  KEY `sales_invoices_customer_id_currency_document_date_index` (`customer_id`,`currency`,`document_date`),
  KEY `sales_invoices_credit_approval_id_foreign` (`credit_approval_id`),
  CONSTRAINT `sales_invoices_approval_id_foreign` FOREIGN KEY (`approval_id`) REFERENCES `workflow_approvals` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `sales_invoices_base_currency_foreign` FOREIGN KEY (`base_currency`) REFERENCES `currencies` (`code`) ON DELETE RESTRICT,
  CONSTRAINT `sales_invoices_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `sales_invoices_credit_approval_id_foreign` FOREIGN KEY (`credit_approval_id`) REFERENCES `workflow_approvals` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `sales_invoices_currency_foreign` FOREIGN KEY (`currency`) REFERENCES `currencies` (`code`) ON DELETE RESTRICT,
  CONSTRAINT `sales_invoices_customer_id_foreign` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `sales_invoices_posted_by_foreign` FOREIGN KEY (`posted_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `sales_invoices_posted_journal_entry_id_foreign` FOREIGN KEY (`posted_journal_entry_id`) REFERENCES `journal_entries` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=46 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

