--
-- Table structure for table `serial_numbers`
--

DROP TABLE IF EXISTS `serial_numbers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `serial_numbers` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `product_id` bigint unsigned NOT NULL,
  `serial_no` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `current_location_id` bigint unsigned DEFAULT NULL,
  `acquisition_cost` decimal(18,4) NOT NULL,
  `receipt_movement_id` bigint unsigned NOT NULL,
  `warranty_start` date DEFAULT NULL,
  `warranty_end` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `sold_sales_line_id` bigint unsigned DEFAULT NULL,
  `customer_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `serial_numbers_serial_no_unique` (`serial_no`),
  KEY `serial_numbers_current_location_id_foreign` (`current_location_id`),
  KEY `serial_numbers_receipt_movement_id_foreign` (`receipt_movement_id`),
  KEY `serial_availability_index` (`product_id`,`status`,`current_location_id`),
  KEY `serial_numbers_sold_sales_line_id_foreign` (`sold_sales_line_id`),
  KEY `serial_numbers_customer_id_foreign` (`customer_id`),
  CONSTRAINT `serial_numbers_current_location_id_foreign` FOREIGN KEY (`current_location_id`) REFERENCES `stock_locations` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `serial_numbers_customer_id_foreign` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `serial_numbers_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `serial_numbers_receipt_movement_id_foreign` FOREIGN KEY (`receipt_movement_id`) REFERENCES `inventory_movements` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `serial_numbers_sold_sales_line_id_foreign` FOREIGN KEY (`sold_sales_line_id`) REFERENCES `sales_invoice_lines` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=446 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

