/*!50003 CREATE*/ /*!50017 DEFINER=`erp_store`@`127.0.0.1`*/ /*!50003 TRIGGER `pi_lines_immutable_update` BEFORE UPDATE ON `supplier_invoice_lines` FOR EACH ROW BEGIN IF EXISTS (SELECT 1 FROM supplier_invoices WHERE id=NEW.supplier_invoice_id AND status='posted') OR EXISTS (SELECT 1 FROM supplier_invoices WHERE id=OLD.supplier_invoice_id AND status='posted') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Posted supplier invoice lines are immutable'; END IF; END */;;
