DROP TABLE IF EXISTS `supplier_invoices`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `supplier_invoices` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `document_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `supplier_id` bigint unsigned NOT NULL,
  `supplier_snapshot` json NOT NULL,
  `supplier_invoice_no` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `invoice_date` date NOT NULL,
  `posting_date` date NOT NULL,
  `due_date` date NOT NULL,
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `version` int unsigned NOT NULL DEFAULT '1',
  `currency` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `base_currency` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `exchange_rate` decimal(18,8) NOT NULL,
  `exchange_rate_date` date NOT NULL,
  `exchange_rate_source` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `net_total` decimal(18,4) NOT NULL,
  `tax_total` decimal(18,4) NOT NULL,
  `foreign_total` decimal(18,4) NOT NULL,
  `base_net_total` decimal(18,4) NOT NULL,
  `base_tax_total` decimal(18,4) NOT NULL,
  `base_total` decimal(18,4) NOT NULL,
  `grni_total` decimal(18,4) NOT NULL,
  `price_variance_total` decimal(18,4) NOT NULL,
  `fx_variance_total` decimal(18,4) NOT NULL,
  `policy_version` int unsigned NOT NULL,
  `policy_snapshot` json NOT NULL,
  `variance_reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `posted_journal_entry_id` bigint unsigned DEFAULT NULL,
  `created_by` bigint unsigned NOT NULL,
  `updated_by` bigint unsigned NOT NULL,
  `posted_by` bigint unsigned DEFAULT NULL,
  `posted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `supplier_invoice_number_unique` (`supplier_id`,`supplier_invoice_no`),
  UNIQUE KEY `supplier_invoices_document_no_unique` (`document_no`),
  KEY `supplier_invoices_currency_foreign` (`currency`),
  KEY `supplier_invoices_base_currency_foreign` (`base_currency`),
  KEY `supplier_invoices_posted_journal_entry_id_foreign` (`posted_journal_entry_id`),
  KEY `supplier_invoices_created_by_foreign` (`created_by`),
  KEY `supplier_invoices_updated_by_foreign` (`updated_by`),
  KEY `supplier_invoices_posted_by_foreign` (`posted_by`),
  KEY `supplier_invoices_supplier_id_posting_date_index` (`supplier_id`,`posting_date`),
  KEY `supplier_invoices_status_due_date_index` (`status`,`due_date`),
  CONSTRAINT `supplier_invoices_base_currency_foreign` FOREIGN KEY (`base_currency`) REFERENCES `currencies` (`code`) ON DELETE RESTRICT,
  CONSTRAINT `supplier_invoices_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `supplier_invoices_currency_foreign` FOREIGN KEY (`currency`) REFERENCES `currencies` (`code`) ON DELETE RESTRICT,
  CONSTRAINT `supplier_invoices_posted_by_foreign` FOREIGN KEY (`posted_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `supplier_invoices_posted_journal_entry_id_foreign` FOREIGN KEY (`posted_journal_entry_id`) REFERENCES `journal_entries` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `supplier_invoices_supplier_id_foreign` FOREIGN KEY (`supplier_id`) REFERENCES `suppliers` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `supplier_invoices_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `pi_totals` CHECK (((`net_total` >= 0) and (`tax_total` >= 0) and (`foreign_total` = (`net_total` + `tax_total`)) and (`base_total` = (`base_net_total` + `base_tax_total`)) and (`exchange_rate` > 0)))
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
