--
-- Table structure for table `supplier_ledger_entries`
--

DROP TABLE IF EXISTS `supplier_ledger_entries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `supplier_ledger_entries` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `supplier_id` bigint unsigned NOT NULL,
  `source_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_id` bigint unsigned NOT NULL,
  `event` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `document_no` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `posting_date` date NOT NULL,
  `due_date` date DEFAULT NULL,
  `currency` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `foreign_amount` decimal(18,4) NOT NULL,
  `base_amount` decimal(18,4) NOT NULL,
  `exchange_rate` decimal(18,8) NOT NULL,
  `account_id` bigint unsigned NOT NULL,
  `journal_entry_id` bigint unsigned DEFAULT NULL,
  `created_by` bigint unsigned NOT NULL,
  `created_at` timestamp NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `supplier_ledger_source_unique` (`source_type`,`source_id`,`event`),
  KEY `supplier_ledger_entries_currency_foreign` (`currency`),
  KEY `supplier_ledger_entries_account_id_foreign` (`account_id`),
  KEY `supplier_ledger_entries_journal_entry_id_foreign` (`journal_entry_id`),
  KEY `supplier_ledger_entries_created_by_foreign` (`created_by`),
  KEY `supplier_ledger_entries_supplier_id_currency_posting_date_index` (`supplier_id`,`currency`,`posting_date`),
  CONSTRAINT `supplier_ledger_entries_account_id_foreign` FOREIGN KEY (`account_id`) REFERENCES `accounts` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `supplier_ledger_entries_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `supplier_ledger_entries_currency_foreign` FOREIGN KEY (`currency`) REFERENCES `currencies` (`code`) ON DELETE RESTRICT,
  CONSTRAINT `supplier_ledger_entries_journal_entry_id_foreign` FOREIGN KEY (`journal_entry_id`) REFERENCES `journal_entries` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `supplier_ledger_entries_supplier_id_foreign` FOREIGN KEY (`supplier_id`) REFERENCES `suppliers` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=87 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
