--
-- Table structure for table `supplier_payments`
--

DROP TABLE IF EXISTS `supplier_payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `supplier_payments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `document_no` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `supplier_id` bigint unsigned NOT NULL,
  `supplier_snapshot` json NOT NULL,
  `document_date` date NOT NULL,
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `version` int unsigned NOT NULL DEFAULT '1',
  `currency` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `base_currency` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `exchange_rate` decimal(18,8) NOT NULL,
  `exchange_rate_date` date NOT NULL,
  `exchange_rate_source` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `base_amount` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload` json NOT NULL,
  `method` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `cashbox_id` bigint unsigned DEFAULT NULL,
  `bank_account_id` bigint unsigned DEFAULT NULL,
  `payment_reference` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `posted_journal_entry_id` bigint unsigned DEFAULT NULL,
  `created_by` bigint unsigned NOT NULL,
  `posted_by` bigint unsigned DEFAULT NULL,
  `posted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `supplier_payments_document_no_unique` (`document_no`),
  KEY `supplier_payments_currency_foreign` (`currency`),
  KEY `supplier_payments_base_currency_foreign` (`base_currency`),
  KEY `supplier_payments_cashbox_id_foreign` (`cashbox_id`),
  KEY `supplier_payments_bank_account_id_foreign` (`bank_account_id`),
  KEY `supplier_payments_posted_journal_entry_id_foreign` (`posted_journal_entry_id`),
  KEY `supplier_payments_created_by_foreign` (`created_by`),
  KEY `supplier_payments_posted_by_foreign` (`posted_by`),
  KEY `supplier_payments_supplier_id_currency_document_date_index` (`supplier_id`,`currency`,`document_date`),
  KEY `supplier_payments_status_document_date_index` (`status`,`document_date`),
  CONSTRAINT `supplier_payments_bank_account_id_foreign` FOREIGN KEY (`bank_account_id`) REFERENCES `bank_accounts` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `supplier_payments_base_currency_foreign` FOREIGN KEY (`base_currency`) REFERENCES `currencies` (`code`) ON DELETE RESTRICT,
  CONSTRAINT `supplier_payments_cashbox_id_foreign` FOREIGN KEY (`cashbox_id`) REFERENCES `cashboxes` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `supplier_payments_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `supplier_payments_currency_foreign` FOREIGN KEY (`currency`) REFERENCES `currencies` (`code`) ON DELETE RESTRICT,
  CONSTRAINT `supplier_payments_posted_by_foreign` FOREIGN KEY (`posted_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `supplier_payments_posted_journal_entry_id_foreign` FOREIGN KEY (`posted_journal_entry_id`) REFERENCES `journal_entries` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `supplier_payments_supplier_id_foreign` FOREIGN KEY (`supplier_id`) REFERENCES `suppliers` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `supplier_payments_amount_positive` CHECK (((`amount` >= 0) and (`base_amount` >= 0) and (`exchange_rate` > 0)))
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
