  CONSTRAINT `treasury_movements_session_id_foreign` FOREIGN KEY (`session_id`) REFERENCES `cashier_sessions` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=158 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
